<script setup>defineProps({loading:Boolean,error:String,empty:Boolean,text:{default:'暂时还没有内容'}});defineEmits(['retry']);</script><template><div v-if="loading" class="state" role="status"><span class="spinner"></span><p>正在加载，请稍候…</p></div><div v-else-if="error" class="state error" role="alert"><p>{{error}}</p><button class="btn secondary" @click="$emit('retry')">重新加载</button></div><div v-else-if="empty" class="state"><span class="empty-paw">♡</span><p>{{text}}</p></div></template>
